CREATE FUNCTION public.can_manage_student_records(_inst uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(public.institution_role_of(_inst) IN ('direccion','subdireccion'),false) $$;
REVOKE ALL ON FUNCTION public.can_manage_student_records(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_manage_student_records(uuid) TO authenticated;
CREATE TABLE public.student_record_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL REFERENCES public.institutions(id),student_id uuid NOT NULL,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120),category text NOT NULL CHECK(category IN ('photo','medical','document')),path text NOT NULL UNIQUE,created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.student_record_documents TO authenticated; GRANT ALL ON public.student_record_documents TO service_role;
ALTER TABLE public.student_record_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY record_read ON public.student_record_documents FOR SELECT TO authenticated USING(public.can_manage_student_records(institution_id));
CREATE POLICY record_insert ON public.student_record_documents FOR INSERT TO authenticated WITH CHECK(public.can_manage_student_records(institution_id) AND created_by=auth.uid());
CREATE POLICY record_delete ON public.student_record_documents FOR DELETE TO authenticated USING(public.can_manage_student_records(institution_id));
CREATE TABLE public.student_record_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,institution_id uuid NOT NULL,student_id uuid NOT NULL,document_id uuid NOT NULL,action text NOT NULL,actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.student_record_events TO authenticated; GRANT ALL ON public.student_record_events TO service_role;
ALTER TABLE public.student_record_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY record_event_read ON public.student_record_events FOR SELECT TO authenticated USING(public.can_manage_student_records(institution_id));
CREATE FUNCTION public.guard_student_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_student_records(NEW.institution_id) OR NEW.created_by<>auth.uid() OR NOT EXISTS(SELECT 1 FROM public.institution_members WHERE institution_id=NEW.institution_id AND user_id=NEW.student_id AND member_role='estudiante') OR NEW.path NOT LIKE NEW.institution_id::text||'/'||NEW.student_id::text||'/%' THEN RAISE EXCEPTION 'Expediente no autorizado' USING ERRCODE='42501'; END IF; NEW.created_at=now(); RETURN NEW; END $$;
CREATE TRIGGER guard_student_record BEFORE INSERT ON public.student_record_documents FOR EACH ROW EXECUTE FUNCTION public.guard_student_record();
CREATE FUNCTION public.audit_student_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO public.student_record_events(institution_id,student_id,document_id,action,actor_id) VALUES(NEW.institution_id,NEW.student_id,NEW.id,'added',auth.uid()); RETURN NEW; ELSE INSERT INTO public.student_record_events(institution_id,student_id,document_id,action,actor_id) VALUES(OLD.institution_id,OLD.student_id,OLD.id,'removed',auth.uid()); RETURN OLD; END IF; END $$;
CREATE TRIGGER audit_student_record AFTER INSERT OR DELETE ON public.student_record_documents FOR EACH ROW EXECUTE FUNCTION public.audit_student_record();
CREATE FUNCTION public.student_record_people(_inst uuid) RETURNS TABLE(user_id uuid,display_name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_manage_student_records(_inst) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF; RETURN QUERY SELECT m.user_id,coalesce(nullif(p.display_name,''),'Estudiante') FROM public.institution_members m LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.institution_id=_inst AND m.member_role='estudiante'; END $$;
REVOKE ALL ON FUNCTION public.student_record_people(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.student_record_people(uuid) TO authenticated;
CREATE FUNCTION public.student_record_path_allowed(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.institution_members m WHERE m.institution_id::text=split_part(_path,'/',1) AND m.user_id::text=split_part(_path,'/',2) AND m.member_role='estudiante' AND public.can_manage_student_records(m.institution_id)) $$;
REVOKE ALL ON FUNCTION public.student_record_path_allowed(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.student_record_path_allowed(text) TO authenticated;
CREATE POLICY record_file_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='student-record-files' AND public.student_record_path_allowed(name));
CREATE POLICY record_file_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='student-record-files' AND public.student_record_path_allowed(name) AND EXISTS(SELECT 1 FROM public.student_record_documents d WHERE d.path=name));
CREATE POLICY record_file_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='student-record-files' AND public.student_record_path_allowed(name));